                "Characteristics": {
                    "Hair Color": "Dark",
                    "Posture": "Smiling"
                }
            }
        ],
        "Inanimate Objects": [
            {
                "Category": "Text",
                "Properties": {
                    "Color": "White, Black, Yellow",
                    "Size": "Various",
                    "Style": "Bold, Italic"
                }
            },
            {
                "Category": "Magazine Title",
                "Properties": {
                    "Text": "People",
                    "Color": "White",
                    "Size": "Large"
                }
            }
        ]
    },
    "Activities": [],
    "Contextual Elements": {
        "Time of Day": "N/A",
        "Weather": "N/A"
    },
    "Visual Patterns": {
        "Dominant Colors": [
            "White",
            "Black",
            "Yellow",
            "Orange"
        ],
        "Textures": [
            "Smooth"
        ]
    },
    "Emotional Undertones": "Positive, Happy",
    "Textual Information": "Exclusive! Jessica Alba Love, Family & a Billion-Dollar Empire. September 20, 2021. I'VE HAD TO PAVE MY OWN WAY.",
    "Summary": "The image is a magazine cover featuring a smiling person with text about Jessica Alba and other headlines.",
}
```

**Example 3: Query Image**
```json
{
    "Scene": {
        "Description": "Natural forest environment with dense foliage."
    },
    "Objects": {
        "Living Beings": [
            {
                "Species": "Bear",
                "Characteristics": {
                    "Color": "Brown",
                    "Posture": "Climbing or resting on a tree branch"
                }
            }
        ],
        "Inanimate Objects": [
            {
                "Category": "Tree",
                "Properties": {
                    "Color": "Green and brown",
                    "Size": "Large",
                    "Material": "Wood",
                    "Shape": "Tall with branches covered in moss"
                }
            }
        ]
    },
    "Activities": [
        {
            "Description": "Bear climbing or resting on a tree branch",
            "Participants": [
                "Bear"
            ]
        }
    ],
    "Contextual Elements": {
        "Time of Day": "Not specified",
        "Weather": "Likely damp or rainy, suggested by mossy tree branches"
    },
    "Visual Patterns": {
        "Dominant Colors": [
            "Green",
            "Brown"
        ],
        "Textures": [
            "Mossy",
            "Furry"
        ]
    },
    "Emotional Undertones": "Calm, natural setting",
    "Textual Information": {
        "Main Title": "NATIONAL WILDLIFE",
        "Subtitles": [
            "A FRAGILE EMBRACE",
            "HOW FORESTS HELP SUSTAIN THE PLANET"
        ],
        "Additional Text": [
            "BEAVERS CREATE NEW WETLANDS 14",
            "ODE TO THE ARCTIC REFUGE 32",
            "HEALING ON THE MISSISSIPPI 40",
            "NATIONAL WILDLIFE FEDERATION",
            "AUGUST-SEPTEMBER 2020"
        ]
    },
    "Summary": "The image is a cover of a magazine titled 'NATIONAL WILDLIFE', featuring a bear in a lush, moss-covered forest. The scene conveys a sense of tranquility and highlights the theme of forest conservation.",
}
```

These examples demonstrate:
- **Task-agnosticism:** Descriptions contain no reference to "rule discovery" or the Bongard task structure
- **Completeness:** Hierarchical structure captures scene, objects, activities, relationships, and patterns
- **Reusability:** Same schema applied to all three benchmarks (Bongard-OW, Bongard-HOI, Winoground)

